'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),uid=()=>crypto.randomUUID(),key='recall-studio-v1';
const types={basic:'Question & answer',choice:'Multiple choice',boolean:'True / false',blank:'Fill in the blank'};
const starter={version:1,subjects:[{id:'soc',name:'Sociology',color:'#bc9cf1',topics:['Education','Crime & deviance','Research methods']},{id:'bio',name:'Biology',color:'#91d6ac',topics:['Cell biology','Organisation']},{id:'psy',name:'Psychology',color:'#e8b17b',topics:['Memory','Social influence']}],cards:[],attempts:0,correct:0};
[['soc','Education','What is the hidden curriculum?','The unwritten rules, values and expectations pupils learn through school routines.','basic'],['soc','Crime & deviance','What is the dark figure of crime?','Crime that is not reported to or recorded by the police.','basic'],['bio','Cell biology','Which organelle is the main site of aerobic respiration?','Mitochondrion','choice',['Nucleus','Ribosome','Chloroplast']],['psy','Memory','Working memory is a single, passive store.','False','boolean'],['bio','Cell biology','The movement of water through a partially permeable membrane is called ___.','osmosis','blank'],['psy','Social influence','What is conformity?','A change in behaviour or beliefs as a result of real or imagined group pressure.','basic']].forEach((x,i)=>starter.cards.push({id:uid(),subject:x[0],topic:x[1],q:x[2],a:x[3],type:x[4],options:x[5]||[],star:false,streak:0,created:Date.now()-i*1000}));
let db=starter;try{const raw=localStorage.getItem(key);if(raw)db=validate(JSON.parse(raw));}catch(e){setTimeout(()=>toast('Could not load saved data. Import a backup if needed.'),200)}
let selected='',topic='',stars=false,session=null;
function validate(d){if(!d||d.version!==1||!Array.isArray(d.subjects)||!Array.isArray(d.cards))throw Error('Invalid backup');const ids=new Set();for(const s of d.subjects){if(typeof s.id!=='string'||ids.has(s.id)||typeof s.name!=='string'||!/^#[0-9a-f]{6}$/i.test(s.color)||!Array.isArray(s.topics)||!s.topics.every(t=>typeof t==='string'))throw Error('Invalid subject');ids.add(s.id)}const cardIds=new Set();for(const c of d.cards){if(typeof c.id!=='string'||cardIds.has(c.id)||!ids.has(c.subject)||!Object.hasOwn(types,c.type)||typeof c.q!=='string'||typeof c.a!=='string'||!c.q.trim()||!c.a.trim()||typeof c.topic!=='string'||!Array.isArray(c.options)||!c.options.every(v=>typeof v==='string')||!Number.isFinite(c.created)||!Number.isFinite(c.streak)||c.streak<0)throw Error('Invalid card');if(c.type==='boolean'&&!['True','False'].includes(c.a))throw Error('Invalid true/false answer');if(c.type==='choice'&&(c.options.length<1||new Set([c.a,...c.options].map(normalize)).size!==c.options.length+1))throw Error('Invalid choices');cardIds.add(c.id)}if(!Number.isFinite(d.attempts)||!Number.isFinite(d.correct)||d.correct<0||d.attempts<d.correct)throw Error('Invalid totals');return d}
function persist(){try{localStorage.setItem(key,JSON.stringify(db));return true}catch(e){toast('Storage is full or unavailable. Export a backup now.');$('.save-dot').textContent='● Changes not saved';return false}}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4000)}
function subject(id){return db.subjects.find(s=>s.id===id)}
function filtered(){const text=$('#search').value.toLowerCase(),type=$('#typeFilter').value;let list=db.cards.filter(c=>(!selected||c.subject===selected)&&(!topic||c.topic===topic)&&(!stars||c.star)&&(!type||c.type===type)&&[c.q,c.a,c.topic,subject(c.subject)?.name].join(' ').toLowerCase().includes(text));const sort=$('#sort').value;return list.sort((a,b)=>sort==='az'?a.q.localeCompare(b.q):sort==='old'?a.created-b.created:sort==='weak'?a.streak-b.streak:sort==='mastery'?b.streak-a.streak:b.created-a.created)}
function render(){const list=filtered(),s=subject(selected);$('#total').textContent=db.cards.length;$('#statCards').textContent=db.cards.length;$('#statSubjects').textContent=db.subjects.length;$('#statMastered').textContent=db.cards.filter(c=>c.streak>=3).length;$('#statAccuracy').textContent=db.attempts?Math.round(db.correct/db.attempts*100)+'%':'—';$('#crumb').textContent=s?.name||(stars?'Starred cards':'All flashcards');$('#libraryTitle').textContent=s?.name||(stars?'Starred cards':'Your flashcards');$('#countLabel').textContent=list.length+' cards · '+(s?'Your subject collection':'All your ideas in one place');$('#all').classList.toggle('active',!selected&&!stars);$('#starred').classList.toggle('active',stars);$('#manage').hidden=!s;$('#addTopic').hidden=!s;$('#subjects').innerHTML=db.subjects.map(s=>`<div class="subject-row ${selected===s.id?'selected':''}"><button data-subject="${esc(s.id)}"><i class="dot" style="--color:${s.color}"></i>${esc(s.name)}</button></div>`).join('');$('#topicChips').innerHTML=s?`<button data-topic="" class="${!topic?'selected':''}">All topics</button>`+s.topics.map(t=>`<button data-topic="${esc(t)}" class="${topic===t?'selected':''}">${esc(t)}</button>`).join(''):'';$('#cards').innerHTML=list.map(c=>{const s=subject(c.subject);return `<article class="card" style="--color:${s.color}"><div class="card-top"><span class="badge">● ${esc(s.name)}</span><button class="star ${c.star?'on':''}" data-star="${esc(c.id)}" aria-label="${c.star?'Unstar':'Star'} card">${c.star?'★':'☆'}</button></div><h3>${esc(c.q)}</h3><span class="topic">${esc(c.topic||'General')} · ${types[c.type]}</span><div class="card-bottom"><span>${c.streak>=3?'● Mastered':c.streak?'◐ Learning':'○ New card'}</span><div><button data-edit="${esc(c.id)}">Edit</button><button data-view="${esc(c.id)}">Review ↗</button></div></div></article>`}).join('')||'<div class="empty"><h3>No cards here yet.</h3><p>Create a flashcard or change your filters.</p></div>'}
function show(title,body){$('#modalContent').innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button class="close" aria-label="Close">×</button></div>${body}`;$('.close').onclick=()=>$('#modal').close();if(!$('#modal').open)$('#modal').showModal()}
function selectSubject(id){selected=id;topic='';stars=false;render()}
$('#all').onclick=()=>selectSubject('');$('#starred').onclick=()=>{selected='';topic='';stars=true;render()};$('#subjects').onclick=e=>{const b=e.target.closest('[data-subject]');if(b)selectSubject(b.dataset.subject)};$('#topicChips').onclick=e=>{const b=e.target.closest('[data-topic]');if(b){topic=b.dataset.topic;render()}};$('#search').oninput=render;$('#typeFilter').onchange=render;$('#sort').onchange=render;
$('#cards').onclick=e=>{const b=e.target.closest('button');if(!b)return;const id=b.dataset.star||b.dataset.edit||b.dataset.view,c=db.cards.find(c=>c.id===id);if(!c)return;if(b.dataset.star){c.star=!c.star;persist();render()}else if(b.dataset.edit)editCard(c);else begin([c],'flip')};
function editSubject(s){show(s?'Edit subject':'New subject',`<form id="subjectForm"><label>Subject name<input name="name" required maxlength="70" value="${esc(s?.name||'')}" placeholder="e.g. Sociology"></label><label>Colour<input name="color" type="color" value="${s?.color||'#bc9cf1'}"></label>${s?'<p class="hint">Subcategories</p><div id="topicList"></div>':''}<div class="form-foot">${s?'<button type="button" id="deleteSubject" class="danger">Delete subject</button>':''}<button class="primary">Save subject</button></div></form>`);$('#subjectForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),name=f.get('name').trim();if(!name)return;if(db.subjects.some(x=>x.id!==s?.id&&x.name.toLowerCase()===name.toLowerCase()))return toast('A subject with that name already exists.');if(s){s.name=name;s.color=f.get('color')}else{const n={id:uid(),name,color:f.get('color'),topics:[]};db.subjects.push(n);selected=n.id;topic='';stars=false}persist();render();$('#modal').close()};if(s){$('#topicList').innerHTML=s.topics.map((t,i)=>`<div class="topic-item"><span>${esc(t)}</span><div><button type="button" data-rename="${i}">Rename</button> <button type="button" data-remove="${i}">Remove</button></div></div>`).join('')||'<p class="hint">No subcategories yet.</p>';$('#topicList').onclick=e=>{const b=e.target.closest('button');if(!b)return;const i=Number(b.dataset.rename??b.dataset.remove),old=s.topics[i];if(b.dataset.rename!==undefined){topicEditor(s,old)}else{confirmAction('Remove subcategory?', 'Cards in this subcategory will move to General.',()=>{s.topics.splice(i,1);db.cards.filter(c=>c.subject===s.id&&c.topic===old).forEach(c=>c.topic='');topic='';persist();render();editSubject(s)})}};$('#deleteSubject').onclick=()=>confirmAction('Delete this subject?',`This deletes ${db.cards.filter(c=>c.subject===s.id).length} cards and all its subcategories. Export a backup first if needed.`,()=>{db.cards=db.cards.filter(c=>c.subject!==s.id);db.subjects=db.subjects.filter(x=>x.id!==s.id);selected='';topic='';persist();render();$('#modal').close()})}}
function confirmAction(title,message,fn){show(title,`<p class="hint">${esc(message)}</p><div class="form-foot"><button id="cancel">Cancel</button><button id="confirm" class="danger">Confirm</button></div>`);$('#cancel').onclick=()=>$('#modal').close();$('#confirm').onclick=fn}
function topicEditor(s,old){show(old?'Rename subcategory':'New subcategory',`<form id="topicForm"><label>Name<input name="name" required maxlength="70" value="${esc(old||'')}" placeholder="e.g. Education"></label><button class="primary">Save subcategory</button></form>`);$('#topicForm').onsubmit=e=>{e.preventDefault();const name=new FormData(e.target).get('name').trim();if(!name)return;if(s.topics.some(t=>t!==old&&t.toLowerCase()===name.toLowerCase()))return toast('That subcategory already exists.');if(old){s.topics[s.topics.indexOf(old)]=name;db.cards.filter(c=>c.subject===s.id&&c.topic===old).forEach(c=>c.topic=name)}else s.topics.push(name);topic=name;persist();render();$('#modal').close()}}
$('#addSubject').onclick=()=>editSubject();$('#manage').onclick=()=>editSubject(subject(selected));$('#addTopic').onclick=()=>topicEditor(subject(selected));
function editCard(c){if(!db.subjects.length){toast('Create a subject first.');return editSubject()}show(c?'Edit flashcard':'Create a flashcard',`<form id="cardForm"><div class="row"><label>Subject<select name="subject" id="cardSubject">${db.subjects.map(s=>`<option value="${esc(s.id)}" ${s.id===(c?.subject||selected)?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label><label>Subcategory<select name="topic" id="cardTopic"></select></label></div><label>Question style<select name="type" id="cardType">${Object.entries(types).map(([v,t])=>`<option value="${v}" ${v===c?.type?'selected':''}>${t}</option>`).join('')}</select></label><label>Question / statement<textarea name="q" required maxlength="3000" placeholder="What would you like to remember?">${esc(c?.q||'')}</textarea></label><p id="typeHint" class="hint"></p><div id="answerField"></div><label>Extra explanation (optional)<textarea name="explanation" maxlength="5000" placeholder="Add context to show after answering…">${esc(c?.explanation||'')}</textarea></label><div class="form-foot">${c?'<button type="button" id="deleteCard" class="danger">Delete card</button>':''}<button class="primary">Save flashcard</button></div></form>`);function topics(){const s=subject($('#cardSubject').value);$('#cardTopic').innerHTML='<option value="">General</option>'+s.topics.map(t=>`<option ${t===(c?.topic||topic)?'selected':''}>${esc(t)}</option>`).join('')}function answer(){const t=$('#cardType').value;$('#typeHint').textContent=t==='blank'?'Use ___ in your question to show the missing word.':t==='boolean'?'Write a statement above, then choose whether it is true or false.':t==='choice'?'Add the correct answer and one to three distinct wrong answers.':'Write a clear answer. Use flip cards for long explanations.';$('#answerField').innerHTML=t==='boolean'?`<label>Correct answer<select name="a"><option ${c?.a==='True'?'selected':''}>True</option><option ${c?.a==='False'?'selected':''}>False</option></select></label>`:`<label>Correct answer<textarea name="a" required maxlength="5000">${esc(c?.a||'')}</textarea></label>${t==='choice'?`<label>Wrong answers — one per line<textarea name="options" required placeholder="Wrong answer 1&#10;Wrong answer 2&#10;Wrong answer 3">${esc((c?.options||[]).join('\n'))}</textarea></label>`:''}`};topics();answer();$('#cardSubject').onchange=topics;$('#cardType').onchange=answer;$('#cardForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),q=f.get('q').trim(),a=f.get('a').trim(),type=f.get('type'),options=String(f.get('options')||'').split('\n').map(x=>x.trim()).filter(Boolean);if(!q||!a)return toast('Add a question and answer.');if(type==='blank'&&!q.includes('___'))return toast('Include ___ for the missing word.');if(type==='choice'&&(options.length<1||options.length>3||new Set([a,...options].map(normalize)).size!==options.length+1))return toast('Add 1–3 different wrong answers, distinct from the correct answer.');const data={subject:f.get('subject'),topic:f.get('topic'),type,q,a,options,explanation:f.get('explanation').trim()};if(c)Object.assign(c,data,{streak:0});else db.cards.push({...data,id:uid(),created:Date.now(),star:false,streak:0});persist();render();$('#modal').close();toast('Flashcard saved')};if(c)$('#deleteCard').onclick=()=>confirmAction('Delete flashcard?','This removes the card and its review progress.',()=>{db.cards=db.cards.filter(x=>x.id!==c.id);persist();render();$('#modal').close()})}
$('#newCard').onclick=()=>editCard();
function shuffle(a){a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}function normalize(s){return String(s).trim().toLowerCase().replace(/\s+/g,' ').replace(/[.!?]+$/,'')}
function setup(){const list=filtered();if(!list.length)return toast('Add cards or clear your filters first.');show('Make it stick',`<p class="hint">Study the ${list.length} cards in your current selection.</p><form id="sessionForm"><label>Study mode<select name="mode"><option value="flip">Flip cards — reveal and rate yourself</option><option value="mixed">Mixed quiz — use each card’s question style</option><option value="typed">Written answers — type from memory</option><option value="choice">Multiple choice — answer options from your cards</option></select></label><div class="row"><label>Number of questions<select name="limit"><option value="10">Up to 10</option><option value="20">Up to 20</option><option value="50">Up to 50</option><option value="all">All cards</option></select></label><label>Card order<select name="order"><option value="shuffle">Shuffle</option><option value="weak">Needs practice first</option><option value="current">Current order</option></select></label></div><p class="hint">Written answers ignore case and extra spaces. Longer explanations can be self-marked after checking the answer. Multiple choice falls back to a written answer when no distinct alternatives exist.</p><button class="primary full">Start session ↗</button></form>`);$('#sessionForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);let cards=f.get('order')==='shuffle'?shuffle(list):f.get('order')==='weak'?[...list].sort((a,b)=>a.streak-b.streak):list;cards=cards.slice(0,f.get('limit')==='all'?cards.length:Number(f.get('limit')));begin(cards,f.get('mode'))}}
$('#start').onclick=setup;$('#practice').onclick=setup;$('#studyFiltered').onclick=setup;
function begin(cards,mode){session={cards,mode,index:0,results:[],revealed:false,answered:false};question()}
function question(){const s=session;if(s.index>=s.cards.length)return results();const c=s.cards[s.index];s.answered=false;s.revealed=false;let mode=s.mode==='mixed'?(c.type==='choice'?'choice':c.type==='boolean'?'boolean':'typed'):s.mode;let choices=[];if(mode==='choice'){const pool=c.options.length?c.options:db.cards.filter(x=>x.id!==c.id&&x.subject===c.subject).map(x=>x.a);let alts=[...new Set(pool)].filter(a=>normalize(a)!==normalize(c.a));if(!alts.length)alts=[...new Set(db.cards.map(x=>x.a))].filter(a=>normalize(a)!==normalize(c.a));choices=shuffle([c.a,...shuffle(alts).slice(0,3)]);if(choices.length<2)mode='typed'}if(mode==='boolean')choices=['True','False'];show(s.mode==='flip'?'Focus mode':'Quiz time',`<p class="hint">${esc(subject(c.subject).name)} / ${esc(c.topic||'General')} <span style="float:right">${s.index+1} / ${s.cards.length}</span></p><div class="progress"><div style="width:${s.index/s.cards.length*100}%"></div></div><div class="study-card"><small id="faceLabel">${mode==='boolean'?'True or false?':'Question'}</small><h3 id="faceText">${esc(c.q)}</h3></div><div id="answerArea">${mode==='flip'?'<button id="reveal" class="primary full">Reveal answer ↻</button>':mode==='typed'?'<form id="typedForm"><label class="field">Your answer<textarea id="typedAnswer" required placeholder="Type what you remember…"></textarea></label><button class="primary full">Check answer</button></form>':`<div class="choices">${choices.map((v,i)=>`<button data-choice="${i}">${esc(v)}</button>`).join('')}</div>`}</div><div id="feedbackArea" aria-live="polite"></div>`);if(mode==='flip')$('#reveal').onclick=()=>{$('#faceLabel').textContent='Answer';$('#faceText').textContent=c.a;$('#answerArea').innerHTML='<div class="row"><button id="again">Still learning</button><button id="known" class="primary">Got it ✓</button></div>';if(c.explanation)$('#feedbackArea').textContent=c.explanation;$('#again').onclick=()=>score(false,'Self-rated: still learning');$('#known').onclick=()=>score(true,'Self-rated: got it')};else if(mode==='typed')$('#typedForm').onsubmit=e=>{e.preventDefault();const value=$('#typedAnswer').value.trim();if(value)score(normalize(value)===normalize(c.a),value,true)};else $('#answerArea').onclick=e=>{const b=e.target.closest('[data-choice]');if(b)score(normalize(choices[Number(b.dataset.choice)])===normalize(c.a),choices[Number(b.dataset.choice)])}}
function score(correct,answer,selfMark=false){const s=session;if(s.answered)return;s.answered=true;const c=s.cards[s.index];s.results.push({id:c.id,q:c.q,a:c.a,answer,correct,previousStreak:c.streak});c.streak=correct?c.streak+1:0;db.attempts++;if(correct)db.correct++;persist();render();$('#answerArea').innerHTML='';$('#feedbackArea').innerHTML=`<div class="feedback ${correct?'':'wrong'}"><b>${correct?'Correct — nice work.':'Keep practising.'}</b><p>${esc(c.a)}</p>${c.explanation?`<p>${esc(c.explanation)}</p>`:''}</div>${selfMark&&!correct?'<p class="hint">Same meaning, different wording? You can mark your answer correct.</p><button id="override">My answer was correct</button>':''}<div class="form-foot"><button id="next" class="primary">${s.index+1===s.cards.length?'See results':'Next card →'}</button></div>`;if($('#override'))$('#override').onclick=()=>{const r=s.results[s.results.length-1];if(r.correct)return;r.correct=true;c.streak=r.previousStreak+1;db.correct++;persist();render();$('#override').disabled=true;$('#override').textContent='Marked correct ✓';$('.feedback').classList.remove('wrong');$('.feedback b').textContent='Marked correct'};$('#next').onclick=()=>{s.index++;question()}}
function results(){const s=session,correct=s.results.filter(r=>r.correct).length,missed=s.results.filter(r=>!r.correct);show('Session complete',`<p class="hint" style="text-align:center">One step closer to knowing it by heart.</p><div class="result">${Math.round(correct/s.results.length*100)}<small>%</small></div><p style="text-align:center">${correct} of ${s.results.length} correct · ${missed.length} to revisit</p><div class="row">${missed.length?'<button id="retry">Practise missed cards</button>':''}<button id="done" class="primary">Back to my cards</button></div>${missed.length?'<h3>Worth another look</h3>'+missed.map(r=>`<div class="review-item"><b>${esc(r.q)}</b><p class="hint">Your answer: ${esc(r.answer)}</p><p>${esc(r.a)}</p></div>`).join(''):''}`);$('#done').onclick=()=>$('#modal').close();if($('#retry'))$('#retry').onclick=()=>begin(missed.map(r=>db.cards.find(c=>c.id===r.id)).filter(Boolean),s.mode)}
$('#export').onclick=()=>{const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(db,null,2)],{type:'application/json'}));a.href=url;a.download='recall-backup-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup exported')};$('#import').onclick=()=>$('#file').click();$('#file').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>10*1024*1024)throw Error('Backup exceeds 10 MB');const data=validate(JSON.parse(await file.text()));confirmAction('Restore backup?',`Replace your current collection with ${data.cards.length} cards and ${data.subjects.length} subjects? Export your current collection first to keep it.`,()=>{db=data;selected='';topic='';stars=false;persist();render();$('#modal').close();toast('Backup restored')})}catch(err){toast('Could not import: '+err.message)}};
render();
